import{_ as e,o,c as r,a3 as s}from"./chunks/framework.CZBGEXos.js";const n="/manual/img/obras/listado.png",t="/manual/img/obras/nueva-obra.png",i="/manual/img/obras/ficha-detalle.png",q=JSON.parse('{"title":"Obras","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/obras.md","filePath":"modulos/obras.md"}'),l={name:"modulos/obras.md"};function c(d,a,u,p,g,m){return o(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="obras" tabindex="-1">Obras <a class="header-anchor" href="#obras" aria-label="Permalink to &quot;Obras&quot;">​</a></h1><p>Una <strong>obra</strong> es cada proyecto de construcción que gestionas dentro de la plataforma. Es el punto de partida de todo tu trabajo: dentro de una obra viven sus documentos de seguridad, las personas asignadas, las actividades, los incidentes y el seguimiento del cumplimiento del DS 44.</p><p>Piensa en la obra como la &quot;carpeta madre&quot; de un proyecto. Mientras no tengas al menos una obra creada, no podrás cargar documentos, asignar trabajadores ni registrar capacitaciones. Por eso, <strong>lo primero que harás al empezar es crear tu obra</strong>.</p><blockquote><p>💡 <strong>¿Quién puede crear obras?</strong> Solo los roles <strong>Administrador</strong> y <strong>Prevencionista</strong>. Si tu rol es Jefe de Obra, Supervisor o Trabajador, podrás ver y trabajar dentro de las obras a las que te asignen, pero no crear nuevas. Revisa <a href="/manual/roles/">Roles de Usuario</a> para ver el detalle de permisos.</p></blockquote><h2 id="entrar-al-modulo-de-obras" tabindex="-1">Entrar al módulo de Obras <a class="header-anchor" href="#entrar-al-modulo-de-obras" aria-label="Permalink to &quot;Entrar al módulo de Obras&quot;">​</a></h2><ol><li>Inicia sesión en la plataforma.</li><li>En el <strong>menú lateral izquierdo</strong>, haz clic en <strong>Obras</strong>.</li><li>Se abrirá la pantalla <strong>Obras</strong>, con el subtítulo <em>&quot;Proyectos activos, documentos DS44 y personal asignado&quot;</em>.</li></ol><p><img src="'+n+'" alt="Listado de obras en vista de tarjetas, con el botón Nueva obra arriba a la derecha"></p><p>Aquí verás todas las obras de tu empresa. Cada obra se muestra como una <strong>tarjeta</strong> con:</p><ul><li>La <strong>foto</strong> de la obra (si se cargó una; si no, aparece una imagen por defecto).</li><li>El <strong>nombre</strong> del proyecto.</li><li>Una etiqueta de <strong>estado</strong> de color: verde (<strong>Activa</strong>), amarillo (<strong>Pausada</strong>) o gris (<strong>Finalizada</strong>).</li><li>La <strong>comuna y región</strong> donde se ubica.</li><li>Un indicador rojo de <strong>DS44 pendientes</strong> cuando a la obra le faltan documentos obligatorios. Si está todo al día, no aparece la alerta.</li></ul><h3 id="buscar-y-filtrar-obras" tabindex="-1">Buscar y filtrar obras <a class="header-anchor" href="#buscar-y-filtrar-obras" aria-label="Permalink to &quot;Buscar y filtrar obras&quot;">​</a></h3><p>Cuando tengas muchas obras, usa las herramientas de la parte superior del listado:</p><ul><li><strong>Buscador:</strong> escribe en el campo <em>&quot;Buscar por nombre, código o dirección…&quot;</em> para filtrar al instante.</li><li><strong>Filtro por estado:</strong> el desplegable te permite mostrar <strong>Todos los estados</strong>, <strong>Activas</strong>, <strong>Pausadas</strong> o <strong>Finalizadas</strong>.</li><li><strong>Vista:</strong> puedes alternar entre <strong>vista de tarjetas</strong> (con foto) y <strong>vista de tabla</strong> (más compacta, ideal para revisar muchas obras de un vistazo).</li></ul><blockquote><p>📌 Si recién creaste tu empresa y todavía no hay obras, verás el mensaje <em>&quot;Sin obras registradas&quot;</em> con un botón directo para crear la primera.</p></blockquote><h2 id="crear-una-obra-nueva" tabindex="-1">Crear una obra nueva <a class="header-anchor" href="#crear-una-obra-nueva" aria-label="Permalink to &quot;Crear una obra nueva&quot;">​</a></h2><ol><li>En la pantalla <strong>Obras</strong>, haz clic en el botón <strong>+ Nueva obra</strong> (arriba a la derecha).</li><li>Se abrirá el formulario <strong>Nueva obra</strong>, dividido en secciones. Complétalas de arriba hacia abajo.</li></ol><p><img src="'+t+'" alt="Formulario de creación de obra con las secciones Identificación, Ubicación y Características DS44"></p><h3 id="seccion-identificacion" tabindex="-1">Sección &quot;Identificación&quot; <a class="header-anchor" href="#seccion-identificacion" aria-label="Permalink to &quot;Sección &quot;Identificación&quot;&quot;">​</a></h3><ul><li><strong>Nombre de obra</strong> <em>(obligatorio)</em> — el nombre con el que identificarás el proyecto. Por ejemplo: <em>&quot;Torre Costanera Norte&quot;</em>.</li><li><strong>Código</strong> <em>(opcional)</em> — un código interno de tu empresa, si usas alguno (ej.: <em>&quot;OBR-001&quot;</em>).</li><li><strong>Mandante</strong> — se completa <strong>automáticamente</strong> con el nombre de tu empresa. Normalmente no necesitas modificarlo.</li><li><strong>Estado</strong> — elige entre <strong>Activa</strong>, <strong>Pausada</strong> o <strong>Finalizada</strong>. Al crear una obra nueva, lo habitual es dejarla en <strong>Activa</strong>.</li></ul><h3 id="seccion-ubicacion" tabindex="-1">Sección &quot;Ubicación&quot; <a class="header-anchor" href="#seccion-ubicacion" aria-label="Permalink to &quot;Sección &quot;Ubicación&quot;&quot;">​</a></h3><ul><li><strong>Región</strong> <em>(obligatorio)</em> — selecciona la región desde el desplegable (puedes escribir para buscarla más rápido).</li><li><strong>Comuna</strong> <em>(obligatorio)</em> — se habilita una vez que eliges la región, y muestra solo las comunas de esa región.</li><li><strong>Dirección</strong> <em>(obligatorio)</em> — empieza a escribir y el sistema te sugerirá direcciones para que selecciones la correcta.</li></ul><h3 id="seccion-caracteristicas-ds44" tabindex="-1">Sección &quot;Características DS44&quot; <a class="header-anchor" href="#seccion-caracteristicas-ds44" aria-label="Permalink to &quot;Sección &quot;Características DS44&quot;&quot;">​</a></h3><p>Aquí marcas las casillas que correspondan a tu obra. <strong>Estas respuestas definen qué exigencias del DS 44 aplican</strong>, para que la plataforma no te pida documentos que tu obra no necesita:</p><ul><li>☐ <strong>Comparte sitio con otra(s) entidad(es)</strong> — faena compartida (Art. 20).</li><li>☐ <strong>Hay máquinas / herramientas motrices</strong> (Art. 10).</li><li>☐ <strong>Existen agentes físicos, químicos o biológicos</strong> (Art. 2).</li></ul><blockquote><p>✅ Tómate un momento para responder bien estas casillas: de ellas depende qué procedimientos y documentos te pedirá el sistema más adelante. Si tu situación cambia, podrás ajustarlas después desde la obra.</p></blockquote><h3 id="seccion-imagen-de-referencia-opcional" tabindex="-1">Sección &quot;Imagen de referencia&quot; (opcional) <a class="header-anchor" href="#seccion-imagen-de-referencia-opcional" aria-label="Permalink to &quot;Sección &quot;Imagen de referencia&quot; (opcional)&quot;">​</a></h3><p>Haz clic en <strong>Seleccionar imagen</strong> para subir una foto del terreno o de la obra. Es solo referencial (te ayuda a identificarla en el listado), pero no es obligatoria.</p><h3 id="seccion-trabajadores-asignados-opcional" tabindex="-1">Sección &quot;Trabajadores asignados&quot; (opcional) <a class="header-anchor" href="#seccion-trabajadores-asignados-opcional" aria-label="Permalink to &quot;Sección &quot;Trabajadores asignados&quot; (opcional)&quot;">​</a></h3><p>Verás la lista de personas registradas en tu empresa. <strong>Marca las casillas</strong> de quienes trabajarán en esta obra desde el inicio. No te preocupes si todavía no lo tienes claro: podrás agregar o quitar personas en cualquier momento desde la ficha de la obra.</p><h3 id="guardar" tabindex="-1">Guardar <a class="header-anchor" href="#guardar" aria-label="Permalink to &quot;Guardar&quot;">​</a></h3><p>Cuando completes los campos obligatorios, haz clic en <strong>Crear obra</strong> (mientras se procesa verás <em>&quot;Creando…&quot;</em>). Si prefieres descartar, usa <strong>Cancelar</strong>.</p><blockquote><p>⚙️ <strong>Qué pasa al guardar:</strong> la plataforma <strong>prepara automáticamente los documentos obligatorios</strong> que el DS 44 exige según las características que marcaste. No tienes que crearlos uno por uno: ya quedan listos, esperando que subas los archivos correspondientes.</p></blockquote><h2 id="abrir-la-ficha-de-una-obra" tabindex="-1">Abrir la ficha de una obra <a class="header-anchor" href="#abrir-la-ficha-de-una-obra" aria-label="Permalink to &quot;Abrir la ficha de una obra&quot;">​</a></h2><p>Haz clic sobre cualquier obra del listado para abrir su <strong>ficha de detalle</strong>. Dentro encontrarás tres pestañas en la parte superior:</p><p><img src="'+i+'" alt="Ficha de detalle de una obra mostrando las pestañas Resumen, DS44 — Cumplimiento y Equipo"></p><ul><li><strong>Resumen</strong> — una vista rápida del estado de la obra: firmas pendientes, documentos DS44 pendientes, actividades del mes e incidentes abiertos.</li><li><strong>DS44 — Cumplimiento</strong> — el corazón de la obra. Aquí gestionas todo el cumplimiento normativo paso a paso (ver más abajo).</li><li><strong>Equipo (N)</strong> — las personas asignadas a la obra. El número entre paréntesis indica cuántas hay activas. Desde aquí asignas o quitas trabajadores y revisas su onboarding.</li></ul><blockquote><p>📋 Junto al nombre de la obra hay un pequeño botón para <strong>copiar su identificador</strong>. Solo lo necesitarás si algún día el soporte te lo pide; en el uso diario puedes ignorarlo.</p></blockquote><h2 id="la-pestana-ds44-—-cumplimiento-el-ciclo-de-mejora" tabindex="-1">La pestaña &quot;DS44 — Cumplimiento&quot; (el ciclo de mejora) <a class="header-anchor" href="#la-pestana-ds44-—-cumplimiento-el-ciclo-de-mejora" aria-label="Permalink to &quot;La pestaña &quot;DS44 — Cumplimiento&quot; (el ciclo de mejora)&quot;">​</a></h2><p>El cumplimiento de una obra <strong>no avanza por etapas de construcción</strong>, sino por un <strong>ciclo de mejora continua</strong> dividido en cuatro fases que se completan en orden:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANIFICAR  →  HACER  →  VERIFICAR  →  ACTUAR</span></span></code></pre></div><ul><li><strong>Planificar</strong> — cargas los documentos base de la obra (política, reglamento, matrices de riesgo, etc.). Cuando están todos, la obra avanza sola a la siguiente fase.</li><li><strong>Hacer</strong> — ejecutas lo planificado: onboarding de los trabajadores, procedimientos, capacitaciones y firmas.</li><li><strong>Verificar</strong> — revisas que todo se haya cumplido y dejas el registro consolidado.</li><li><strong>Actuar</strong> — das seguimiento a las medidas correctivas surgidas de incidentes.</li></ul><p>Para pasar de una fase a la siguiente, completa lo que la fase pide y usa el botón de <strong>avanzar fase</strong> que aparece en pantalla. El sistema <strong>no te dejará avanzar dejando pendientes obligatorios</strong>, para que no queden vacíos de cumplimiento.</p><blockquote><p>⚠️ Avanzar de fase es un paso importante del proceso. Asegúrate de haber completado realmente lo que corresponde antes de confirmar.</p></blockquote><h2 id="asignar-personas-a-la-obra" tabindex="-1">Asignar personas a la obra <a class="header-anchor" href="#asignar-personas-a-la-obra" aria-label="Permalink to &quot;Asignar personas a la obra&quot;">​</a></h2><ol><li>Abre la ficha de la obra y entra a la pestaña <strong>Equipo</strong>.</li><li>Usa la opción de <strong>asignar trabajadores</strong> para sumar personas de tu empresa a la obra.</li><li>Al asignar a alguien, podrás indicar su <strong>cargo</strong> dentro de esta obra. El cargo define qué documentos y capacitaciones de onboarding necesitará esa persona.</li></ol><p>Cada trabajador asignado muestra su <strong>avance de onboarding</strong> y si ya está <strong>apto para ingresar a terreno</strong> (es decir, si completó todos sus requisitos obligatorios).</p><h2 id="editar-pausar-o-finalizar-una-obra" tabindex="-1">Editar, pausar o finalizar una obra <a class="header-anchor" href="#editar-pausar-o-finalizar-una-obra" aria-label="Permalink to &quot;Editar, pausar o finalizar una obra&quot;">​</a></h2><p>Desde la ficha de la obra puedes:</p><ul><li><strong>Editar</strong> sus datos (nombre, ubicación, características DS44, etc.) con el botón de edición (ícono de lápiz).</li><li><strong>Pausar</strong> la obra cambiando su estado a <em>Pausada</em>, si los trabajos se detienen temporalmente. La obra conserva toda su información.</li><li><strong>Finalizar</strong> la obra cambiando su estado a <em>Finalizada</em> cuando el proyecto concluye.</li></ul><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Puedo tener varias obras al mismo tiempo?</strong> Sí. Tu empresa puede gestionar todas las obras que necesites de forma simultánea, cada una con su propio cumplimiento, equipo y documentos.</p><p><strong>No veo el botón &quot;+ Nueva obra&quot;.</strong> Ese botón solo aparece para los roles <strong>Administrador</strong> y <strong>Prevencionista</strong>. Si no lo ves, es porque tu rol no tiene permiso para crear obras. Pídele a un administrador que la cree y te asigne.</p><p><strong>Creé la obra pero no veo los documentos.</strong> Los documentos obligatorios se generan solos al guardar la obra. Ábrela, entra a la pestaña <strong>DS44 — Cumplimiento</strong> y los verás listados, esperando que subas cada archivo.</p><p><strong>¿Por qué a mi obra le aparece una alerta roja de &quot;DS44 pendientes&quot;?</strong> Significa que faltan documentos obligatorios por cargar. El número indica cuántos. Entra a la pestaña <strong>DS44 — Cumplimiento</strong> para completarlos; cuando estén todos, la alerta desaparece.</p><p><strong>Me equivoqué al marcar las características DS44 al crear la obra.</strong> Puedes corregirlas editando la obra desde su ficha. Ten en cuenta que cambiarlas puede modificar qué documentos te exige el sistema.</p><p><strong>El sistema no me deja avanzar de fase.</strong> Es intencional: quedan requisitos obligatorios sin completar en la fase actual. Revisa qué está pendiente en la pestaña <strong>DS44 — Cumplimiento</strong>, complétalo y vuelve a intentar.</p><p><strong>¿Qué diferencia hay entre pausar y finalizar una obra?</strong><strong>Pausar</strong> es temporal: la obra se detiene pero puedes retomarla. <strong>Finalizar</strong> marca el cierre del proyecto. En ambos casos la información se conserva y puedes consultarla.</p>',56)])])}const h=e(l,[["render",c]]);export{q as __pageData,h as default};
